/* No theme class: follow the OS. */
:root:not(.light, .dark, [data-theme]) {
  color-scheme: light dark;
}

.dark,
[data-theme="dark"] {
  color-scheme: dark;
}

.light,
[data-theme="light"] {
  color-scheme: light;
}

@media (prefers-color-scheme: light) {
  :root:not(.dark):not([data-theme="dark"]) {
    --kilt-sh-plate: 0 1px 2px rgb(0 0 0 / .05);
    --kilt-sh-card: 0 0 0 .5px rgb(0 0 0 / .11);
    --kilt-sh-row-open: inset 0 0 0 1px rgb(0 0 0 / .08);
    --kilt-sh-overlay: 0 6px 18px rgb(0 0 0 / .03), 0 3px 9px rgb(0 0 0 / .04), 0 1px 1px rgb(0 0 0 / .05);
    --kilt-sh-composer: 0 4px 12px rgb(0 0 0 / .025), 0 2px 6px rgb(0 0 0 / .03), 0 1px 1px rgb(0 0 0 / .04);
    --kilt-sh-sheet: 0 9px 48px rgb(0 0 0 / .08), 0 6px 24px rgb(0 0 0 / .1), 0 1px 1px rgb(0 0 0 / .04);
  }
}

.dark,
[data-theme="dark"] {
  --kilt-sh-plate: 0 .5px 1px 1px rgb(0 0 0 / .3);
  --kilt-sh-card: 0 0 0 1px rgb(0 0 0 / .3);
  --kilt-sh-row-open: none;
  --kilt-sh-overlay: 0 3px 8px rgb(0 0 0 / .13), 0 2px 5px rgb(0 0 0 / .13), 0 1px 1px rgb(0 0 0 / .13);
  --kilt-sh-composer: 0 3px 8px rgb(0 0 0 / .09), 0 2px 5px rgb(0 0 0 / .09), 0 1px 1px rgb(0 0 0 / .1);
  --kilt-sh-sheet: var(--kilt-sh-overlay);
}

.light,
[data-theme="light"] {
  --kilt-sh-plate: 0 1px 2px rgb(0 0 0 / .05);
  --kilt-sh-card: 0 0 0 .5px rgb(0 0 0 / .11);
  --kilt-sh-row-open: inset 0 0 0 1px rgb(0 0 0 / .08);
  --kilt-sh-overlay: 0 6px 18px rgb(0 0 0 / .03), 0 3px 9px rgb(0 0 0 / .04), 0 1px 1px rgb(0 0 0 / .05);
  --kilt-sh-composer: 0 4px 12px rgb(0 0 0 / .025), 0 2px 6px rgb(0 0 0 / .03), 0 1px 1px rgb(0 0 0 / .04);
  --kilt-sh-sheet: 0 9px 48px rgb(0 0 0 / .08), 0 6px 24px rgb(0 0 0 / .1), 0 1px 1px rgb(0 0 0 / .04);
}

[data-density="touch"] {
  --kilt-spacing-icon-xs: 14px;
