@media (prefers-reduced-motion: reduce) {
  [class*="kilt-"],
  [class*="kilt-"] * {
    animation-duration: 1ms !important;
    transition-duration: 1ms !important;
  }
}

/* motion (cds/guidelines.md) */
@property --kilt-duration-exit { syntax: "<time>"; inherits: true; initial-value: 120ms; }
@property --kilt-duration-tooltip-exit { syntax: "<time>"; inherits: true; initial-value: 110ms; }
@property --kilt-delay-hover { syntax: "<time>"; inherits: true; initial-value: 350ms; }
@property --kilt-scale-overlay-from { syntax: "<number>"; inherits: true; initial-value: 0.97; }
@property --kilt-scale-dialog-from { syntax: "<number>"; inherits: true; initial-value: 0.95; }
@property --kilt-scale-toast-from { syntax: "<number>"; inherits: true; initial-value: 0.8; }
@property --kilt-shift-pane-from { syntax: "<length>"; inherits: true; initial-value: 4px; }
:root {
  --kilt-duration-exit: 120ms; /* Overlay exit */
  --kilt-duration-tooltip-exit: 110ms; /* Tooltip exit */
  --kilt-delay-hover: 350ms; /* Tooltip and preview card open delay */
  --kilt-scale-overlay-from: 0.97; /* Menu, popover, preview card enter/exit scale */
  --kilt-scale-dialog-from: 0.95; /* Dialog and command palette enter scale */
  --kilt-scale-toast-from: 0.8; /* Toast enter scale */
  --kilt-shift-pane-from: 4px; /* Right pane enter offset */
}

/* Component hooks: override per subtree. */
:root {
  --kilt-focus-ring: var(--kilt-color-ring);
  --kilt-composer-surface: var(--kilt-color-card);
}
